-- 提示：订单头在 orders，金额在 order_items，订单级指标要先聚合到订单粒度
SELECT '2024-01' AS month, COUNT(*) AS orders_cnt, 0 AS gmv, 0 AS aov
FROM orders WHERE status = '已完成';

SELECT status, 0 AS order_cnt, 0 AS ratio
FROM orders
GROUP BY status;

